package io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.app;
import org.apache.kafka.clients.admin.NewTopic;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;import org.springframework.kafka.config.*;import org.springframework.kafka.core.KafkaTemplate;import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.consumer.*;import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.model.TakeoverEvent;import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.producer.TakeoverPublisher;
@Configuration(proxyBeanMethods=false)@EnableAutoConfiguration@ConditionalOnProperty(name="scenario.takeover.enabled",havingValue="true")@Import(TakeoverScenarioController.class)
public class TakeoverScenarioApplication {@Bean NewTopic topic(@Value("${app.kafka.topics.takeover}")String t){return TopicBuilder.name(t).partitions(2).replicas(1).build();}@Bean TakeoverTracker tracker(){return new TakeoverTracker();}@Bean TakeoverPublisher publisher(KafkaTemplate<String,TakeoverEvent> t){return new TakeoverPublisher(t);}@Bean TakeoverConsumerA a(TakeoverTracker t){return new TakeoverConsumerA(t);}@Bean TakeoverConsumerB b(TakeoverTracker t){return new TakeoverConsumerB(t);}@Bean TakeoverConsumerControl control(KafkaListenerEndpointRegistry r){return new TakeoverConsumerControl(r);}@Bean TakeoverExperiment experiment(TakeoverPublisher p,TakeoverTracker t,TakeoverConsumerControl c,@Value("${app.kafka.topics.takeover}")String topic){return new TakeoverExperiment(p,t,c,topic);}}
